import Foundation

/// ~5s of synthesized speech (16 kHz mono, 16-bit LE PCM, base64) used to warm
/// the Whisper decoder at launch. A real-speech decode exercises the full
/// autoregressive path so the first dictation isn't slow — noise/silence don't
/// generate enough tokens to compile it. Generated with `say` + `afconvert`.
enum PrimingAudio {
    static var samples: [Float] {
        guard let data = Data(base64Encoded: pcm16Base64) else { return [] }
        return data.withUnsafeBytes { raw -> [Float] in
            raw.bindMemory(to: Int16.self).map { Float(Int16(littleEndian: $0)) / 32768.0 }
        }
    }

    private static let pcm16Base64 = ""
}
